local rounds = {configs = {{id = 1, name = "Round 1", desc = "Scout Invasion", targetScore = 200, enemies = {scout = 1.0, fighter = 0, tank = 0, speeder = 0}, spawnRate = 1.2, speedMult = 1.0},{id = 2, name = "Round 2", desc = "Fighter Squadron", targetScore = 500, enemies = {scout = 0.5, fighter = 0.5, tank = 0, speeder = 0}, spawnRate = 1.0, speedMult = 1.1},{id = 3, name = "Round 3", desc = "Heavy Armor", targetScore = 1000, enemies = {scout = 0.3, fighter = 0.4, tank = 0.3, speeder = 0}, spawnRate = 0.85, speedMult = 1.2},{id = 4, name = "Round 4", desc = "Speed Raid", targetScore = 1800, enemies = {scout = 0.2, fighter = 0.3, tank = 0.2, speeder = 0.3}, spawnRate = 0.7, speedMult = 1.3},{id = 5, name = "Round 5", desc = "Total War", targetScore = 3000, enemies = {scout = 0.2, fighter = 0.25, tank = 0.25, speeder = 0.3}, spawnRate = 0.6, speedMult = 1.4},{id = 6, name = "Round 6", desc = "Endless Mode", targetScore = 999999, enemies = {scout = 0.2, fighter = 0.25, tank = 0.25, speeder = 0.3}, spawnRate = 0.5, speedMult = 1.5},}}
function rounds.getConfig(roundNum) return rounds.configs[math.min(roundNum, #rounds.configs)] end
function rounds.checkAdvance(score, roundNum) return score >= rounds.getConfig(roundNum).targetScore end
function rounds.getEnemyType(roundNum, score) local cfg = rounds.getConfig(roundNum); local r, cum = math.random(), 0; for etype, prob in pairs(cfg.enemies) do cum = cum + prob; if r <= cum then return etype end end; return "scout" end
function rounds.getSpawnRate(roundNum) return rounds.getConfig(roundNum).spawnRate end
function rounds.getSpeedMult(roundNum) return rounds.getConfig(roundNum).speedMult end
return rounds
